1	import java.math.BigDecimal;
2	import java.util.Map;
3	
4	/**
5	 * The MHPCO price list: what the office charges as a base premium for each item type
6	 * it covers, and what it insures that type for, before any modifier that depends on
7	 * the item, the customer or the contract. A lookup only -- the offers the office makes
8	 * on top of these prices, such as the component building block, live with the pricing
9	 * that grants them.
10	 */
11	public final class MhpcoPriceList {
12	
13	    /**
14	     * One row of the price list: the two figures the list states side by side for an
15	     * item type. They are quoted together and revised together, so the list records
16	     * them together.
17	     */
18	    private record Entry(int basePremium, int insuranceValue) {
19	    }
20	
21	    /** The main item types the office covers, each with its row of the price list. */
22	    private static final Map<String, Entry> MAIN_ITEMS = Map.of(
23	            "sword", new Entry(100, 1000),
24	            "amulet", new Entry(60, 600),
25	            "staff", new Entry(80, 800),
26	            "potion", new Entry(40, 400));
27	
28	    /**
29	     * Components are a family of small item types the MHPCO prices alike: every
30	     * component costs the same base premium and is insured at the same value,
31	     * whatever its type.
32	     */
33	    private static final Map<String, Entry> COMPONENTS = Map.of(
34	            "rune", new Entry(25, 250),
35	            "moonstone", new Entry(25, 250));
36	
37	    static final int COMPONENT_BASE_PREMIUM = COMPONENTS.get("rune").basePremium();
38	
39	    private MhpcoPriceList() {
40	    }
41	
42	    /**
43	     * What a single item costs on its own, ignoring any building block it belongs to.
44	     * Item risk surcharges are shares of this amount.
45	     */
46	    public static BigDecimal basePremiumOf(Item item) {
47	        return BigDecimal.valueOf(entryFor(item).basePremium());
48	    }
49	
50	    /**
51	     * What the office insures a single item for. Unlike the base premium, this is
52	     * never reduced by an offer: a building block is cheaper to insure, not worth less.
53	     */
54	    public static int insuranceValueOf(Item item) {
55	        return entryFor(item).insuranceValue();
56	    }
57	
58	    /** Whether the office prices this item as a component rather than a main item. */
59	    public static boolean isComponent(Item item) {
60	        return COMPONENTS.containsKey(item.type());
61	    }
62	
63	    /**
64	     * The row the office reads for this item. The MHPCO covers only what its price
65	     * list names: an item of any other type is not insurable here.
66	     */
67	    private static Entry entryFor(Item item) {
68	        Entry component = COMPONENTS.get(item.type());
69	        if (component != null) {
70	            return component;
71	        }
72	        Entry mainItem = MAIN_ITEMS.get(item.type());
73	        if (mainItem == null) {
74	            throw new IllegalArgumentException(
75	                    "the MHPCO does not cover items of type: " + item.type());
76	        }
77	        return mainItem;
78	    }
79	}
