     1	import java.util.List;
     2	
     3	/**
     4	 * A contract the MHPCO has written: the items it covers, the premium charged, and
     5	 * how much of its payout cap is still available.
     6	 */
     7	public final class Policy {
     8	
     9	    /** The office never pays out more than this multiple of the insurance sum. */
    10	    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    11	
    12	    private final List<Item> items;
    13	    private final int premium;
    14	    private int remainingCap;
    15	
    16	    public Policy(List<Item> items, int premium) {
    17	        this.items = List.copyOf(items);
    18	        this.premium = premium;
    19	        this.remainingCap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum();
    20	    }
    21	
    22	    /**
    23	     * The insured item a reported damage names. The office matches a damage to the
    24	     * first covered item of that type: what the policy covers is the policy's own
    25	     * knowledge, so the policy answers the question rather than handing out its items.
    26	     *
    27	     * <p>Deliberately incomplete: the specification rejects a claim whose damage names
    28	     * an item the policy does not cover, and equally a claim reporting more damages of
    29	     * a type than the policy insures -- which this lookup would instead resolve to the
    30	     * same item twice. Neither rejection is implemented yet, so an uncovered type
    31	     * surfaces only as a bare lookup failure. Both are decisions about what this policy
    32	     * covers, and belong here when they come.
    33	     */
    34	    Item insuredItemFor(Damage damage) {
    35	        return items.stream()
    36	                .filter(item -> item.type().equals(damage.itemType()))
    37	                .findFirst()
    38	                .orElseThrow();
    39	    }
    40	
    41	    public int premium() {
    42	        return premium;
    43	    }
    44	
    45	    /** What remains of the total the office will pay out over this policy's life. */
    46	    public int remainingCap() {
    47	        return remainingCap;
    48	    }
    49	
    50	    /**
    51	     * The office draws a settled payout against the policy's cap and pays out what
    52	     * the cap still allows: a desired payout beyond the remaining cap is reduced to
    53	     * it. The cap is the policy's own ledger -- only the policy knows how much of it
    54	     * earlier claims have already spent.
    55	     */
    56	    int drawAgainstCap(int desiredPayout) {
    57	        int paid = Math.min(desiredPayout, remainingCap);
    58	        remainingCap -= paid;
    59	        return paid;
    60	    }
    61	
    62	    /** What the policy insures in total: the sum of its items' insurance values. */
    63	    private int insuranceSum() {
    64	        return items.stream().mapToInt(MhpcoPriceList::insuranceValueOf).sum();
    65	    }
    66	}
