     1	import java.math.BigDecimal;
     2	import java.math.RoundingMode;
     3	
     4	/**
     5	 * How the MHPCO settles damage reported against a policy: it resolves each reported
     6	 * damage to the insured item it names, asks its reimbursement clauses how much of
     7	 * that damage it recognises, withholds the deductible per damage event, and pays out
     8	 * the total.
     9	 *
    10	 * <p>Separate from what the office charges: a premium is priced from the price list,
    11	 * the customer's file and the item's risk, while a payout is decided from the damage
    12	 * and the damaged item alone. The two change for different reasons -- so much so that
    13	 * the office's own favour points in opposite directions, rounding a premium up but a
    14	 * payout down.
    15	 */
    16	public final class ClaimSettlement {
    17	
    18	    /** The MHPCO keeps this much of every damage event to itself. */
    19	    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = BigDecimal.valueOf(100);
    20	
    21	    private ClaimSettlement() {
    22	    }
    23	
    24	    /** What the office pays out for everything the incident damaged. */
    25	    public static Settlement forIncident(Policy policy, Incident incident) {
    26	        BigDecimal payout = incident.damages().stream()
    27	                .map(damage -> reimbursementFor(damage, policy.insuredItemFor(damage)))
    28	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    29	        int paid = policy.drawAgainstCap(roundInOfficeFavour(payout));
    30	        return new Settlement(paid, policy.remainingCap());
    31	    }
    32	
    33	    /** What the office reimburses for one damaged item, after its deductible. */
    34	    private static BigDecimal reimbursementFor(Damage damage, Item item) {
    35	        return ReimbursementClause.recognisedAmountOf(damage, item)
    36	                .subtract(DEDUCTIBLE_PER_DAMAGE);
    37	    }
    38	
    39	    /**
    40	     * A payout is rounded down: the MHPCO rounds in its own favour. Intermediate
    41	     * amounts stay exact fractions, so only this final step loses the remainder.
    42	     */
    43	    private static int roundInOfficeFavour(BigDecimal payout) {
    44	        return payout.setScale(0, RoundingMode.FLOOR).intValueExact();
    45	    }
    46	}
