     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The MHPCO's clauses on how much of a reported damage it recognises at all, before
     5	 * the deductible is withheld. A clause looks only at the damaged item and the amount
     6	 * claimed: it is the office's statement about the risk the item carried, not about
     7	 * the customer, the contract or the price list.
     8	 *
     9	 * <p>The office knows two clauses, and reads them in this order of precedence:
    10	 *
    11	 * <ol>
    12	 *   <li>Damage to a highly enchanted item (enchantment level &gt;= 8) is recognised
    13	 *       at half. This clause wins wherever it applies.</li>
    14	 *   <li>Damage to an item of dragon material is recognised in full.</li>
    15	 * </ol>
    16	 *
    17	 * <p>Only the first clause is encoded below, and deliberately so. Full recognition is
    18	 * already the office's default for every damage no clause touches, so the dragon-material
    19	 * clause prescribes exactly what would happen without it: it is stated by the tariff but
    20	 * changes no amount. Encoding it would mean a branch returning the same figure as the
    21	 * fall-through, which no claim could ever tell apart -- the office would be unable to
    22	 * check the clause it had written down. The clause is therefore recorded here rather
    23	 * than in code, and {@link Item#material()} accordingly bears on no payout today. Should
    24	 * the office ever lower its default recognition below full, this clause becomes
    25	 * observable and earns its branch, immediately above the default.
    26	 *
    27	 * <p>The recognised amount stays an exact fraction -- a halved damage of an odd amount is
    28	 * genuinely a half-G, and the MHPCO's rounding belongs to the final payout alone.
    29	 */
    30	public final class ReimbursementClause {
    31	
    32	    /** From this enchantment level on, the office recognises only half a damage. */
    33	    private static final int HALVED_REIMBURSEMENT_ENCHANTMENT = 8;
    34	
    35	    private static final BigDecimal HALF = BigDecimal.valueOf(5, 1);
    36	
    37	    private ReimbursementClause() {
    38	    }
    39	
    40	    /** How much of this damage to this item the office recognises. */
    41	    public static BigDecimal recognisedAmountOf(Damage damage, Item item) {
    42	        BigDecimal claimed = BigDecimal.valueOf(damage.amount());
    43	        if (isHighlyEnchanted(item)) {
    44	            return claimed.multiply(HALF);
    45	        }
    46	        return claimed;
    47	    }
    48	
    49	    /** Whether the halving clause reaches this item at all. */
    50	    private static boolean isHighlyEnchanted(Item item) {
    51	        return item.enchantment() >= HALVED_REIMBURSEMENT_ENCHANTMENT;
    52	    }
    53	}
