     5	public class ClaimOffice {
     6	
     7	    private static final BigDecimal PROCESSING_FEE = BigDecimal.valueOf(5);
     8	
     9	    private final Customer customer;
    10	    private final ContractHistory contractHistory = new ContractHistory();
    11	
    12	    public ClaimOffice(Customer customer) {
    13	        this.customer = customer;
    14	    }
    15	
    16	    /**
    17	     * The office quotes the premium for the items and, in doing so, writes the
    18	     * contract: the premium is priced against the customer's file as it stands, and
    19	     * only then does the new contract enter that file.
    20	     */
    21	    public int quote(List<Item> items) {
    22	        int premium = premiumFor(items);
    23	        contractHistory.recordContractWritten();
    24	        return premium;
    25	    }
    26	
    27	    /** The office writes a policy for the items, charging the quoted premium. */
    28	    public Policy insure(List<Item> items) {
    29	        return new Policy(items, quote(items));
    30	    }
    31	
    32	    /** The office settles a claim reported against one of its policies. */
    33	    public Settlement claim(Policy policy, Incident incident) {
    34	        return ClaimSettlement.forIncident(policy, incident);
    35	    }
    36	
    37	    /** What the office charges for these items: every scope's contribution, plus the fee. */
    38	    private int premiumFor(List<Item> items) {
    39	        BigDecimal premiumBeforeFee = PolicyModifiers.applyTo(
    40	                        PolicyBasePremium.of(items),
    41	                        customer.isLongStanding(),
    42	                        contractHistory.nextContractIsFollowUp())
    43	                .add(ItemRiskRating.surchargesFor(items));
    44	        return roundInOfficeFavour(premiumBeforeFee.add(PROCESSING_FEE));
    45	    }
    46	
    47	    /**
    48	     * A premium is rounded up: the MHPCO rounds in its own favour. Intermediate
    49	     * amounts stay exact fractions, so only this final step loses the remainder.
    50	     */
    51	    private static int roundInOfficeFavour(BigDecimal premium) {
    52	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    53	    }
    54	}
