     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The modifiers the MHPCO applies to a policy as a whole, as opposed to the risk it
     5	 * rates on an individual item. Each is a share of the policy base premium: the office
     6	 * charges for taking on a contract, not for the particular items in it.
     7	 *
     8	 * <p>The office knows three, and they stack additively on the same base:
     9	 *
    10	 * <ul>
    11	 *   <li>a 10 % initial assessment surcharge, levied on every quote -- each item in a
    12	 *       quote is a first insurance, whatever the customer's history;</li>
    13	 *   <li>a 20 % loyalty discount for a long-standing customer;</li>
    14	 *   <li>a 15 % discount on every contract after the customer's first.</li>
    15	 * </ul>
    16	 *
    17	 * <p>Separate from {@link ItemRiskRating}: these change when the office revises the
    18	 * terms it offers a customer, while an item surcharge changes when the office revises
    19	 * the risk it sees in an item. The processing fee is neither -- it is a flat charge
    20	 * added after every modifier, so it stays with the office's final reckoning.
    21	 */
    22	public final class PolicyModifiers {
    23	
    24	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = Modifier.rate(10);
    25	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = Modifier.rate(20);
    26	    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = Modifier.rate(15);
    27	
    28	    private PolicyModifiers() {
    29	    }
    30	
    31	    /**
    32	     * The policy base premium adjusted by every policy-wide modifier that applies to
    33	     * this contract.
    34	     */
    35	    public static BigDecimal applyTo(
    36	            BigDecimal policyBasePremium, boolean longStandingCustomer, boolean followUpContract) {
    37	        BigDecimal adjusted = policyBasePremium
    38	                .add(policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE));
    39	        if (longStandingCustomer) {
    40	            adjusted = adjusted.subtract(policyBasePremium.multiply(LOYALTY_DISCOUNT_RATE));
    41	        }
    42	        if (followUpContract) {
    43	            adjusted = adjusted.subtract(
    44	                    policyBasePremium.multiply(FOLLOW_UP_CONTRACT_DISCOUNT_RATE));
    45	        }
    46	        return adjusted;
    47	    }
    48	}
